import data.behirtung as tables
import rego.v1

size_ok if record.general.participation_year > 1

size_ok if {
	record.general.participation_year == 1
	record.general.protected_at_ha >= 0.5
}

size_ok if {
	record.general.participation_year == 1
	record.general.qualifying_at_ha >= 1.5
}

